<script setup lang="ts">
import {computed,ref} from 'vue';import {Sparkles,FileText} from 'lucide-vue-next';import {ElMessage} from 'element-plus';import {useAppStore,time} from '../store';import type {Report} from '../types';
const app=useAppStore();const busy=ref(false),selected=ref<number|null>(null),evidence=ref<string[]>([]);const report=computed(()=>app.data?.reports.find(r=>r.id===selected.value)??app.data?.reports[0]);
async function generate(useAi=false){busy.value=true;try{const r=await app.call<Report>('generate_report',{useAi});await app.refresh();selected.value=r.id;ElMessage.success(r.kind==='fallback'?'AI 不可用，已生成本地报告':'报告已生成');}catch(e){ElMessage.error(String(e));}finally{busy.value=false;}}
</script>
<template><section class="welcome"><div><span class="eyebrow accent">EVIDENCE FIRST</span><h2>你的教练，和数据站在一起。</h2><p>先做确定性分析，再解释原因；每一次鼓励都能找到依据。</p></div><Sparkles :size="64" :stroke-width="1" class="accent"/></section><div class="toolbar"><el-button type="primary" :loading="busy" :disabled="app.preview" @click="generate(false)"><FileText :size="16"/> 生成本地每日报告</el-button><el-button :loading="busy" :disabled="app.preview||!app.data?.settings.ai_consent" @click="generate(true)"><Sparkles :size="16"/> 请求 AI 补充解释</el-button><span class="muted push-right">{{app.data?.settings.ai_consent?'已授权发送聚合统计':'AI 未授权 · 本地教练可离线使用'}}</span></div><div class="coach-layout"><section class="panel report-body"><template v-if="report"><div class="panel-heading"><h3>{{report.date}} 训练分析</h3><span class="status improved">{{report.kind==='ai'?'本地证据 + AI 解释':report.kind==='fallback'?'本地报告 · AI 回退':'本地规则报告'}}</span></div><p class="muted small">生成时间 {{time(report.generated_at)}}</p><div class="report-text">{{report.text}}</div><el-collapse v-model="evidence"><el-collapse-item title="查看分析依据（与模型发送内容相同，不含源文件路径）" name="evidence"><pre>{{JSON.stringify(report.evidence,null,2)}}</pre></el-collapse-item></el-collapse></template><div v-else class="empty"><h3>还没有教练报告</h3><p>导入训练记录后，会自动保存本地总结。也可以随时生成报告。</p><p class="muted">没有记录时会明确显示数据不足，不会编造进步结论。</p></div></section><aside class="panel report-history"><h3>成长档案</h3><button v-for="r in app.data?.reports??[]" :key="r.id" :class="{active:report?.id===r.id}" @click="selected=r.id"><strong>{{r.date}}</strong><small>{{time(r.generated_at)}}</small><span>{{r.kind==='ai'?'AI 补充':'本地分析'}}</span></button><p v-if="!app.data?.reports.length" class="muted small">生成过的报告会保存在本地数据库。</p></aside></div><section class="panel"><h3>训练会话与表现衰减</h3><p class="muted small">连续记录间隔不超过 {{app.data?.settings.session_gap_minutes??20}} 分钟视为同一会话，这是 AimCoach 产品规则。只比较同一场景，至少9次且三段中位数持续下降才提示。</p><div v-for="s in app.data?.sessions.slice(0,5)??[]" :key="s.start" class="session-row"><div>{{time(s.start)}} → {{time(s.end)}}<span class="muted">　{{s.count}} 次记录</span></div><p v-for="note in s.decay" :key="note" class="warning">{{note}}</p><small v-if="!s.decay.length" class="muted">未检测到满足规则的持续衰减信号。</small></div><p v-if="!app.data?.sessions.length" class="muted">暂无训练会话。</p></section></template>
